@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2 class="mb-3">Project Board</h2>

@if (_error is not null)
{
    <div class="alert alert-danger">@_error</div>
}
else if (_loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else
{
    <!-- Stats bar -->
    <div class="d-flex flex-wrap gap-3 mb-3">
        <span class="badge bg-secondary fs-6">Total: @_allTasks.Count</span>
        <span class="badge bg-primary fs-6">To Do: @TasksInColumn("To Do").Count</span>
        <span class="badge bg-warning text-dark fs-6">In Progress: @TasksInColumn("In Progress").Count</span>
        <span class="badge bg-success fs-6">Done: @TasksInColumn("Done").Count</span>
        <span class="badge bg-danger fs-6">Overdue: @_allTasks.Count(t => t.DueDate.Date < DateTime.Today)</span>
    </div>

    <!-- Search -->
    <div class="mb-3" style="max-width: 400px;">
        <input type="text" class="form-control" placeholder="Search tasks by title…"
               @bind="_searchText" @bind:event="oninput" />
    </div>

    <!-- Columns -->
    <div class="row g-3">
        @foreach (var col in _columns)
        {
            var filtered = FilteredTasksInColumn(col);
            <div class="col-md-4">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between align-items-center fw-bold">
                        <span>@col</span>
                        <span class="badge bg-secondary rounded-pill">@filtered.Count</span>
                    </div>
                    <div class="card-body d-flex flex-column gap-2 overflow-auto" style="max-height: 65vh;">
                        @foreach (var task in filtered)
                        {
                            <div class="card shadow-sm">
                                <div class="card-body p-2">
                                    <h6 class="card-title mb-1">@task.Title</h6>
                                    <p class="mb-1 text-muted small">@task.Assignee</p>
                                    <div class="d-flex justify-content-between align-items-center mb-1">
                                        <span class="badge @PriorityClass(task.Priority)">@task.Priority</span>
                                        <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
                                    </div>
                                    <div class="d-flex gap-1">
                                        @if (ColumnIndex(col) > 0)
                                        {
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    @onclick="() => MoveTask(task, _columns[ColumnIndex(col) - 1])">
                                                ← Move Left
                                            </button>
                                        }
                                        @if (ColumnIndex(col) < _columns.Length - 1)
                                        {
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    @onclick="() => MoveTask(task, _columns[ColumnIndex(col) + 1])">
                                                Move Right →
                                            </button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        @if (_addingInColumn == col)
                        {
                            <div class="card border-primary">
                                <div class="card-body p-2 d-flex flex-column gap-2">
                                    <input type="text" class="form-control form-control-sm"
                                           placeholder="Title" @bind="_newTitle" />
                                    <input type="text" class="form-control form-control-sm"
                                           placeholder="Assignee" @bind="_newAssignee" />
                                    <select class="form-select form-select-sm" @bind="_newPriority">
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                    </select>
                                    <input type="date" class="form-control form-control-sm" @bind="_newDueDate" />
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-primary btn-sm" @onclick="SaveNewTask">Save</button>
                                        <button class="btn btn-secondary btn-sm" @onclick="CancelAdd">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>
                    <div class="card-footer">
                        <button class="btn btn-outline-primary btn-sm w-100"
                                @onclick="() => StartAdd(col)">
                            + Add Task
                        </button>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private readonly string[] _columns = ["To Do", "In Progress", "Done"];
    private List<TaskItem> _allTasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchText = string.Empty;

    // Inline form state
    private string? _addingInColumn;
    private string _newTitle = string.Empty;
    private string _newAssignee = string.Empty;
    private string _newPriority = "Medium";
    private DateTime _newDueDate = DateTime.Today.AddDays(7);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    private List<TaskItem> TasksInColumn(string status) =>
        _allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> FilteredTasksInColumn(string status) =>
        _allTasks
            .Where(t => t.Status == status &&
                        (string.IsNullOrWhiteSpace(_searchText) ||
                         t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase)))
            .ToList();

    private int ColumnIndex(string col) => Array.IndexOf(_columns, col);

    private static string PriorityClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var idx = _allTasks.IndexOf(task);
            if (idx >= 0)
            {
                _allTasks[idx] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            _error = $"Failed to move task: {ex.Message}";
        }
    }

    private void StartAdd(string column)
    {
        _addingInColumn = column;
        _newTitle = string.Empty;
        _newAssignee = string.Empty;
        _newPriority = "Medium";
        _newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelAdd() => _addingInColumn = null;

    private async Task SaveNewTask()
    {
        if (string.IsNullOrWhiteSpace(_newTitle) || _addingInColumn is null)
            return;

        try
        {
            var created = await TaskService.CreateTaskAsync(_newTitle, _newAssignee, _newPriority, _newDueDate);
            // CreateTaskAsync returns a task with default status; ensure it matches the target column
            if (created.Status != _addingInColumn)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, _addingInColumn);
                created = created with { Status = _addingInColumn };
            }
            _allTasks.Add(created);
            _addingInColumn = null;
        }
        catch (Exception ex)
        {
            _error = $"Failed to create task: {ex.Message}";
        }
    }
}

