+    private List<TaskItem> TasksInColumn(string status) =>
+        _allTasks.Where(t => t.Status == status).ToList();
+
+    private List<TaskItem> FilteredTasksInColumn(string status) =>
+        _allTasks
+            .Where(t => t.Status == status &&
+                        (string.IsNullOrWhiteSpace(_searchText) ||
+                         t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase)))
+            .ToList();
+
+    private int ColumnIndex(string col) => Array.IndexOf(_columns, col);
+
+    private static string PriorityClass(string priority) => priority switch
+    {
+        "High" => "bg-danger",
+        "Medium" => "bg-warning text-dark",
+        "Low" => "bg-success",
+        _ => "bg-secondary"
+    };
+
+    private async Task MoveTask(TaskItem task, string newStatus)
+    {
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
+            var idx = _allTasks.IndexOf(task);
+            if (idx >= 0)
+            {
+                _allTasks[idx] = task with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            _error = $"Failed to move task: {ex.Message}";
+        }
+    }
+
+    private void StartAdd(string column)
+    {
+        _addingInColumn = column;
+        _newTitle = string.Empty;
+        _newAssignee = string.Empty;
+        _newPriority = "Medium";
+        _newDueDate = DateTime.Today.AddDays(7);
+    }
+
+    private void CancelAdd() => _addingInColumn = null;
+
+    private async Task SaveNewTask()
+    {
+        if (string.IsNullOrWhiteSpace(_newTitle) || _addingInColumn is null)
+            return;
+
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(_newTitle, _newAssignee, _newPriority, _newDueDate);
+            // CreateTaskAsync returns a task with default status; ensure it matches the target column
+            if (created.Status != _addingInColumn)
+            {
+                await TaskService.UpdateTaskStatusAsync(created.Id, _addingInColumn);
+                created = created with { Status = _addingInColumn };
+            }
+            _allTasks.Add(created);
+            _addingInColumn = null;
+        }
+        catch (Exception ex)
+        {
+            _error = $"Failed to create task: {ex.Message}";
+        }
+    }
+}
